INSERT INTO posts (title, slug, content, excerpt, image_url, categories, tags, author, wp_id, published, created_at, updated_at)
VALUES ('Volunteering while in Direct Provision', 'post-253298', 'Sofia Clifford-Riordan,
a policy, advocacy and
programmes officer with Dublin
City Community Co-op, has
written a paper exploring the
volunteering experiences of
people in Direct Provision.
She found was "an eagerness"
among asylum-seekers to
volunteer. It was partly explained
by Kristin Kristjansdottir, a
social inclusion officer with
Dublin City Volunteer Centre,
who pointed out that many such
people used to be volunteers
in their own countries, that it
was “a part of their culture,
personality and vision”.
Mhammed used to volunteer
at a music project in his native
Morocco to help steer young
people away from drugs and
alcohol.
"When Mhammed arrived
in Ireland, volunteering was a
natural undertaking to continue,"
writes Sofia. "Being a proficient
English speaker, Mhammed
began to volunteer in the crosscultural classes."
He also volunteers in a charity
shop and a local community
garden.
Musa showed Sofia a picture
of himself volunteering on
St Patrick’s Day, an Irish flag
painted on his smiling face. “I
thought then I am officially an
Irish person," he said jovially.
Salimi from Nigeria used to
volunteer in her local church.
Now, she is involved, with her
three sons, in canal clean-ups.
She also volunteers for two halfday shifts a week in a St Vincent
de Paul charity shop.
W: dublincitycommunitycoop.ie/', 'Mhammed, Musa and Salimi share their experiences', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', 'Changing Ireland', 253298, 0, '2023-07-24T11:55:01Z', '2023-07-24T11:55:01Z')
