INSERT INTO posts (title, slug, content, excerpt, image_url, categories, tags, author, wp_id, published, created_at, updated_at)
VALUES ('* The new head of an Cosán: Heydi Foster Breslin *', 'the-new-head-of-an-cosan-heydi-foster-breslin-2', 'Over 30 years, An Cosán has provided pathways to empowerment through community education.
The mission of An Cosán - (Gaeilge for ‘The Path’) - is to bring about social equality and an end to poverty through community-based adult education, the provision of early years supports and empowering social enterprise development.
Recently, the organisation expanded its reach to a national scale using technology to deliver a range of virtual learning courses.
Originally from Guatemala, Heydi has extensive experience across countries in advocating for equality, human rights and providing social services to minority groups.
Prior to An Cosán, Heydi was CEO of Misean Cara, an Irish development agency working with some of the most marginalised and vulnerable communities in the world.
She has been a Commissioner of the Irish Human Rights and Equality Commission since 2014. She was reappointed by the President for a second five-year term in 2018.', 'Heydi Foster Breslin is the new CEO of An Cosán, the country’s largest community education organisation.', '/files/uploads/2020/07/IMG_0361-scaled.jpg', '[{"slug":"planning-governance","title":"Planning & Governance"}]', '[]', 'Allen Meagher', 249858, 0, '2020-08-25T22:18:15Z', '2020-08-25T22:18:15Z')
